insert into public.industries(id,name) values ('tech','Tech & Software'),('design','Design & Creative'),('business','Business & Finance'),('marketing','Marketing & Sales'),('healthcare','Healthcare'),('education','Education'),('engineering','Engineering'),('other','Other Careers') on conflict(id) do update set name=excluded.name;
insert into public.rooms(slug,name,description,icon,industry_id) values('lounge','The Unemployment Lounge','Different backgrounds. Same browser tabs. Make yourself at home.','☕',null),('tech','Tech & Software','It works on my machine. The job search, less so.','⌘','tech'),('design','Design & Creative','Between pixels, portfolios, and possibilities.','✳','design'),('business','Business & Finance','Let’s circle back to having a salary.','↗','business'),('marketing','Marketing & Sales','Our personal brand is currently available.','◎','marketing'),('healthcare','Healthcare','A little care for the people who care.','♡','healthcare'),('education','Education','Still learning. Always connecting.','▤','education'),('engineering','Engineering','Building bridges to whatever comes next.','⚙','engineering'),('other','Other Careers','You don’t need a label to belong here.','✦','other') on conflict(slug) do update set name=excluded.name,description=excluded.description;
